// Parse e prepara para upsert
const resp = $input.first().json;
const choices = resp.choices || [];
if (choices.length === 0) return [{ json: { skip: true } }];

let parsed = {};
try {
  parsed = JSON.parse(choices[0].message.content);
} catch (e) {
  parsed = { resumo: choices[0].message.content, topicos: [], perfil_inferido: '', proximos_passos: '' };
}

const mobile = $('Variáveis').first().json.mobile;
return [{
  json: {
    telefone: mobile,
    resumo: parsed.resumo || '',
    topicos: Array.isArray(parsed.topicos) ? parsed.topicos.join(', ') : (parsed.topicos || ''),
    perfil_inferido: parsed.perfil_inferido || '',
    proximos_passos: parsed.proximos_passos || '',
    status_atendimento_apos: $('Resolver Sessão').first().json.status_atendimento || 'ativo',
    created_at: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json;
const startDay = body.startDay || new Date().toISOString().slice(0,10);
const endDay = body.endDay || startDay;
const audiencia = (body.audiencia || 'B2B').toUpperCase();

const cacheKey = `grdmad:calcache:${startDay}_${endDay}_${audiencia}`;
return [{ json: { startDay, endDay, audiencia, cacheKey } }];

// Mescla os 3 calendários e calcula slots livres
const input = $('Cal: Parse Input').first().json;
const principal = $('Cal: GET Principal').all().map(i => i.json);
const b2b = $('Cal: GET B2B').all().map(i => i.json);
const b2c = $('Cal: GET B2C').all().map(i => i.json);

// Coletar todos os busy intervals
const busy = [...principal, ...b2b, ...b2c].map(e => {
  const s = e?.start?.dateTime || e?.start?.date;
  const en = e?.end?.dateTime || e?.end?.date;
  if (!s || !en) return null;
  return { start: new Date(s).getTime(), end: new Date(en).getTime(), summary: e.summary || '' };
}).filter(Boolean).sort((a,b) => a.start - b.start);

// Horário comercial por audiência
const ehB2C = input.audiencia === 'B2C';
const morningStart = 9, morningEnd = 12;
const afternoonStart = 14, afternoonEnd = ehB2C ? 19 : 18;
const slotMinutes = 30;

const slots_livres = [];
const slots_ocupados = [];

const startD = new Date(input.startDay + 'T00:00:00-03:00');
const endD = new Date(input.endDay + 'T23:59:59-03:00');

for (let d = new Date(startD); d <= endD; d.setDate(d.getDate() + 1)) {
  const dow = d.getDay(); // 0=dom, 6=sab
  if (dow === 0 || dow === 6) continue; // pula fim de semana

  const dateStr = d.toISOString().slice(0,10);

  // Construir os slots de 30min do dia
  const periodos = [[morningStart, morningEnd], [afternoonStart, afternoonEnd]];
  for (const [h0, h1] of periodos) {
    for (let h = h0; h < h1; h++) {
      for (let m = 0; m < 60; m += slotMinutes) {
        const start = new Date(d);
        start.setHours(h, m, 0, 0);
        const end = new Date(start.getTime() + slotMinutes*60*1000);

        // Verifica colisão
        const colide = busy.some(b => start.getTime() < b.end && end.getTime() > b.start);
        const slot = {
          date: dateStr,
          time: String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0'),
          startISO: start.toISOString(),
          endISO: end.toISOString()
        };

        if (colide) {
          slots_ocupados.push(slot);
        } else {
          // só adiciona se for futuro
          if (start.getTime() > Date.now()) slots_livres.push(slot);
        }
      }
    }
  }
}

// Limita a primeiros 12 slots livres pra LLM não se perder
const result = {
  audiencia: input.audiencia,
  intervalo: { startDay: input.startDay, endDay: input.endDay },
  slots_livres: slots_livres.slice(0, 12),
  total_livres: slots_livres.length,
  cacheKey: input.cacheKey
};

return [{ json: result }];

